using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // ── CalculateTotal: DataRow-driven happy-path tests ─────────────────

    [TestMethod]
    [DataRow(10.00, 1, 0.0,  10.00,  DisplayName = "Single item, no tax")]
    [DataRow(10.00, 2, 0.0,  20.00,  DisplayName = "Two items, no tax")]
    [DataRow(10.00, 1, 0.10, 11.00,  DisplayName = "Single item, 10% tax")]
    [DataRow(25.50, 3, 0.08, 82.62,  DisplayName = "Fractional price, 8% tax")]
    [DataRow(0.00,  5, 0.20, 0.00,   DisplayName = "Zero unit price")]
    [DataRow(99.99, 0, 0.15, 0.00,   DisplayName = "Zero quantity")]
    [DataRow(10.00, 1, 1.0,  20.00,  DisplayName = "100% tax rate (boundary)")]
    public void CalculateTotal_WithValidInputs_ReturnsExpectedTotal(
        double unitPrice, int quantity, double taxRate, double expectedTotal)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expectedTotal, result);
    }

    // ── CalculateTotal: invalid-input tests ─────────────────────────────

    [TestMethod]
    [DataRow(-1.00, 1,  0.10, "unitPrice",  DisplayName = "Negative unit price")]
    [DataRow(10.00, -1, 0.10, "quantity",    DisplayName = "Negative quantity")]
    [DataRow(10.00, 1,  -0.1, "taxRate",     DisplayName = "Negative tax rate")]
    [DataRow(10.00, 1,  1.01, "taxRate",     DisplayName = "Tax rate above 1")]
    public void CalculateTotal_WithInvalidInputs_ThrowsArgumentOutOfRange(
        double unitPrice, int quantity, double taxRate, string expectedParamName)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));

        Assert.AreEqual(expectedParamName, ex.ParamName);
    }

    // ── ApplyDiscount: DynamicData-driven tests ─────────────────────────

    public static IEnumerable<object[]> DiscountTestCases
    {
        get
        {
            yield return [100.00m, 0m,   100.00m, "No discount"];
            yield return [100.00m, 10m,  90.00m,  "10% off"];
            yield return [100.00m, 50m,  50.00m,  "50% off"];
            yield return [100.00m, 100m, 0.00m,   "100% off (free)"];
            yield return [49.99m,  25m,  37.4925m, "Fractional result"];
            yield return [0.00m,   50m,  0.00m,   "Zero price with discount"];
            yield return [200.00m, 33.33m, 133.34m, "Repeating decimal percent"];
        }
    }

    [TestMethod]
    [DynamicData(nameof(DiscountTestCases))]
    public void ApplyDiscount_WithValidInputs_ReturnsExpectedPrice(
        decimal price, decimal discountPercent, decimal expectedPrice, string scenario)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expectedPrice, result, $"Failed for scenario: {scenario}");
    }

    // ── ApplyDiscount: boundary / invalid-input tests ───────────────────

    [TestMethod]
    [DataRow(-0.01, DisplayName = "Discount just below 0%")]
    [DataRow(-50.0, DisplayName = "Negative discount")]
    [DataRow(100.01, DisplayName = "Discount just above 100%")]
    [DataRow(200.0, DisplayName = "Discount way above 100%")]
    public void ApplyDiscount_WithInvalidDiscount_ThrowsArgumentOutOfRange(double discountPercent)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(100m, (decimal)discountPercent));
    }

    // ── FormatPrice: DynamicData from method ────────────────────────────

    public static IEnumerable<object[]> FormatPriceCases()
    {
        yield return [10.00m,   "$",  "$10.00"];
        yield return [10.00m,   "€",  "€10.00"];
        yield return [0.50m,    "£",  "£0.50"];
        yield return [1234.5m,  "$",  "$1234.50"];
        yield return [99.999m,  "$",  "$100.00"];
    }

    [TestMethod]
    [DynamicData(nameof(FormatPriceCases), DynamicDataSourceType.Method)]
    public void FormatPrice_WithVariousCurrencies_ReturnsFormattedString(
        decimal price, string symbol, string expected)
    {
        var result = _calculator.FormatPrice(price, symbol);

        Assert.AreEqual(expected, result);
    }
}

